js.text:

function grid$bcsskhth(f){
  this.constructor(f);
}
grid$bcsskhth.prototype = new DirEvent();
grid$bcsskhth.prototype.afterInitFields = function(){
  var p = this._dir;
}

grid$bcsskhth.prototype.beforeInit = function(){
  var p = this._dir;
}

grid$bcsskhth.prototype.afterInit = function(){
  var p = this._dir;
}

grid$bcsskhth.prototype.beforeRenderGrid = function(g, gdt){
  var p = this._dir, k = g.pivotFields.length;
  while(k--) {
    fi = g.pivotFields[k];
    if (fi.name.indexOf('@4#') != -1 || fi.name.indexOf('@5#') != -1) fi.lastSymbol = '%'
  }
}

css.text:

.toolbar-close > div {
	background-position: -336px -400px !important;
.table-bottom{
	left: 0px!important;
	height: calc(100% - 77px);
	top: 0px;
	position: relative;
	margin-top: 27px;
	clear: both;
	border-bottom: 1px solid #ddd;
}
#content .dir{
	position: relative !important;
	height: 100%;
}

@media only screen and (max-width: 767px) {
  .table-bottom{
	margin-top: 42px;
	height: calc(100% - 92px);
  }
}
